sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director ?deathDate WHERE {
  VALUES (?film ?dirProp) {
    (dbr:Kanchana_Sita dbo:director)
    (dbr:Ghost_of_the_China_Sea dbp:director)
  }
  ?film ?dirProp ?director .
  OPTIONAL { ?director dbp:deathDate ?dbpDeath . }
  OPTIONAL { ?director dbo:deathDate ?dboDeath . }
  BIND (COALESCE(?dbpDeath, ?dboDeath) AS ?deathDate)
}
LIMIT 100

